public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int totalLetters = word1.length() + word2.length() - commonLetters;
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters / totalLetters;
}

