public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k < 2) {
        return false;
    }

    int n = arr.length / 2;
    int[] sums = new int[n];
    for (int i = 0; i < n; i++) {
        sums[i] = arr[i * 2] + arr[i * 2 + 1];
    }

    for (int i = 0; i < n; i++) {
        if (sums[i] % k != 0) {
            return false;
        }
    }

    return true;
}

