public boolean splitArraySameAverage(int[] nums) {
    if (nums.length == 1) {
        return false;
    }
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double avg = total / nums.length;
    double sum1 = 0;
    double sum2 = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        sum1 += nums[i];
        sum2 += nums[i + 1];
        if (sum1 / (i + 1) == avg && sum2 / (nums.length - (i + 1)) == avg) {
            return true;
        }
    }
    return false;
}

