public int minCostClimbingStairs(int[] cost) {
    // Special case: if the array is empty or has only one element, return 0
    if (cost.length == 0 || cost.length == 1) {
        return 0;
    }

    // Initialize the minimum cost for both starting indices (0 and 1)
    int minCost0 = cost[0];
    int minCost1 = cost[1];

    // Loop through the remaining elements and calculate the minimum cost for each starting index
    for (int i = 2; i < cost.length; i++) {
        minCost0 = Math.min(minCost0, minCost1) + cost[i];
        minCost1 = Math.min(minCost0, minCost1) + cost[i];
    }

    // Return the minimum cost for either starting index
    return Math.min(minCost0, minCost1);
}

