public int findMinFibonacciNumbers(int k) {
    int fib1 = 1, fib2 = 1, fib = fib1 + fib2;
    int count = 0;
    while (fib <= k) {
        if (k >= fib) {
            k -= fib;
            count++;
        }
        int temp = fib1;
        fib1 = fib2;
        fib2 = fib;
        fib = temp + fib2;
    }
    return count;
}

