public static boolean isPowerOfTwo(int n) {
    // If n is not positive, return false
    if (n <= 0) {
        return false;
    }
    // If n is 1, return true
    if (n == 1) {
        return true;
    }
    // If n is even, return false
    if (n % 2 == 0) {
        return false;
    }
    // If n is odd, check if n = 2^k for some integer k
    int k = 1;
    while (2 * k <= n) {
        k *= 2;
    }
    return k == n;
}

