public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("The number of points must be 3");
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    int a = (x1 - x3) * (y2 - y3);
    int b = (x2 - x3) * (y1 - y3);
    return 2 * (a + b) == (x1 - x2) * (y1 - y2);
}

