public static int minPerfectSquareSum(int n) {
    int result = 0;
    for (int i = 1; i * i <= n; i++) {
        int numSquares = 1;
        while (n - i * i >= 0) {
            n -= i * i;
            numSquares++;
        }
        if (result > numSquares) {
            result = numSquares;
        }
    }
    return result;
}

